const htmlPath='configurador-3d/fit-lab/index.html';let html=await readFile(htmlPath,'utf8');
const old=/<aside class="reference">[\s\S]*?<\/aside>/;if(!old.test(html))throw Error('Missing reference aside');
html=html.replace(old,`<aside class="reference"><div id="reference-photo-stage" class="reference-photo-stage"><canvas id="full-reference-canvas" aria-label="Referencia 3D sintética de cuerpo completo, 170 centímetros"></canvas><img id="full-reference-photo" alt="Foto de referencia local con marcas de escala" hidden><p class="eyebrow" id="full-reference-title">REFERENCIA 3D · 170 cm</p><p class="reference-crop-label">Cuerpo entero · misma escala y suelo</p></div></aside>`);
const description='*170 cm según la ficha aportada, sin verificar. La barra comparte escala con el avatar. La foto conserva su proporción original: al no incluir los pies, el borde del recorte no representa una medida corporal.';
if(!html.includes(description))throw Error('Missing reference explanation');html=html.replace(description,'Referencia sintética fija de 170 cm, independiente de las medidas del avatar. La foto original está recortada; para comparar una fotografía real carga una toma de cuerpo entero y marca cabeza y pies.');
html=html.replace('<summary>Proyecciones y medidas visibles</summary>',`<summary>Fotografía de referencia y medidas</summary><div class="reference-upload"><label>Referencia<select id="reference-mode"><option value="synthetic">3D fijo · 170 cm</option><option value="photo">Foto local de cuerpo completo</option></select></label><label>Foto completa<input id="reference-file" type="file" accept="image/jpeg,image/png,image/webp"></label><label>Estatura declarada (cm)<input id="reference-height" type="number" min="100" max="220" value="170"></label><label>Cabeza (% desde arriba)<input id="reference-head" type="range" min="0" max="40" value="0"></label><label>Pies (% desde arriba)<input id="reference-feet" type="range" min="50" max="100" value="100"></label><p id="reference-photo-status" class="micro">La foto se procesa solo en esta pestaña. No se envía al servidor.</p><details><summary>Foto original recortada</summary><img id="reference-photo" src="./assets/reference-user.webp" width="300" height="332" alt="Foto original recortada, sin pies. No válida para comparar estaturas." decoding="async"></details></div>`);
html=html.replace('Cuerpo inferior y pantalón: referencia visual, sin simulación de ajuste.','Pantalón: patrón fijo y apoyo geométrico de cintura; gravedad sin simulación textil.');changes.set(htmlPath,html);
const cssPath='configurador-3d/fit-lab/comparison.css';let css=await readFile(cssPath,'utf8');css+=`\n#full-reference-canvas{position:absolute;inset:0;width:100%;height:100%;display:block}#full-reference-canvas[hidden],#full-reference-photo[hidden]{display:none}#full-reference-photo{position:absolute;max-width:none;left:50%;transform:translateX(-50%);object-fit:contain}.reference-photo-stage>.eyebrow{z-index:2;background:#f4f9bfee;right:5px;padding:4px;font-size:8px}.reference-crop-label{font-size:8px}.nominal-catalog{margin-top:12px}.nominal-catalog table{width:100%;border-collapse:collapse;font-size:11px}.nominal-catalog th,.nominal-catalog td{padding:5px;text-align:right;border-bottom:1px solid #d8e5ec}.nominal-catalog th:first-child{text-align:left}.nominal-catalog tr.selected{background:#e5f1f5}.reference-upload{grid-column:1/-1;display:grid;grid-template-columns:1fr 1fr;gap:8px;min-width:0}.reference-upload label{display:grid;gap:4px;font-size:11px}.reference-upload input,.reference-upload select,.shorts-controls select{max-width:100%;width:100%;min-width:0}.reference-upload img{max-width:200px;height:auto}.shorts-controls label{display:grid;gap:5px}.shorts-controls select{padding:8px;border:1px solid #c6dce5;background:white;border-radius:5px}.reference-data details[open]{max-width:100%}@media(max-width:520px){.reference-upload{grid-template-columns:1fr}.reference-photo-stage>.eyebrow{font-size:7px}}\n`;changes.set(cssPath,css);
